/**
 * Per-message model/effort tag inside the assistant message's IconActions row.
 * Reads the addressed assistant message's request config from the session
 * snapshot's `trajectory` view (the same requests the Trajectory panel shows,
 * each with provider/model plus reasoning effort and its result sequence),
 * matched to the message by resultSeq. Absent configs render nothing.
 * @module @deepseek-ai/dsh-client-ui-model-tag/client/ModelEffortTagActions
 */

import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-runtime/client'
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import css from './ModelEffortTagActions.module.css'
import type {} from './locales.ts'

/** Full props of the assistant-message model/effort tag entry. */
export type ModelEffortTagActionProps =
  PropsRuntime<'conversation.chat.assistant-actions'>
  & PropsLocale<'modelEffortTag'>

/** The request-config face we read; structural, decoupled from the trajectory package. */
interface ModelRequestConfig {
  readonly provider?: string
  readonly model?: string
  readonly reasoningEffort?: string
}

/** Narrow structural face of the session snapshot this tag reads. */
interface SnapshotShape {
  readonly nodes: readonly {
    readonly kind: string
    readonly seq: number
    readonly messageId?: string
  }[]
  readonly views: {
    get(target: 'trajectory'): {
      readonly requests: readonly {
        readonly requestConfig?: ModelRequestConfig
        readonly resultSeq?: number
      }[]
    } | undefined
  }
}

/**
 * Resolve the request config of the addressed assistant message, if any.
 * @param snapshot - conversation snapshot from the standard useSession source.
 * @param messageId - the addressed finalized assistant message id.
 * @returns the request config, or undefined when the trajectory view is absent
 *   or no matching request is recorded.
 */
function requestConfigOf(snapshot: SnapshotShape, messageId: string): ModelRequestConfig | undefined {
  for (const node of snapshot.nodes) {
    if (node.kind !== 'assistant' || node.messageId !== messageId) continue
    const inspection = snapshot.views.get('trajectory')
    const request = inspection?.requests.find(candidate => candidate.resultSeq === node.seq)
    return request?.requestConfig
  }
  return undefined
}

/**
 * The tag entry component: a quiet model/effort label for one assistant message.
 * @param props - the addressed message id, the standard useSession source, and the locale seat.
 * @returns the label, or null when the message has no recorded request config.
 */
export function ModelEffortTagActions({ messageId, useSession, t }: ModelEffortTagActionProps) {
  const config = useSession(snapshot => (
    requestConfigOf(snapshot as unknown as SnapshotShape, messageId)
  ))
  const model = config?.model
  if (model === undefined) return null
  const provider = config?.provider
  const effort = config?.reasoningEffort
  // Provider/model · effort — the same provider identity the Trajectory panel
  // records for the request, folded into the per-message IconActions row.
  const label = provider !== undefined ? `${provider}/${model}` : model
  return (
    <span className={css.tag} title={t('tooltip')}>
      {label}
      {effort !== undefined ? ` · ${effort}` : ''}
    </span>
  )
}
